function bankQuestions(key){const ids=D.mapping?.[key]||[];return ids.flatMap(id=>D.quizBanks?.[id]||[])}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function practicePage(){return '<div class="fade-in">'+heading('Small challenges. Real understanding.','Practise a few foundation concepts for your course or exam. Learn from each answer.')+'<div class="filter-bar"><label for="practice-goal">Your path</label><select id="practice-goal">'+goalOptions(labGoal)+'</select></div><div class="game-pickers"><button class="game-picker '+(gameStyle==='blocks'?'active':'')+'" data-game-style="blocks"><span class="pixel-block">\u25A6</span><strong>Block builder</strong><small>Get concepts right. Build your tower.</small></button><button class="game-picker '+(gameStyle==='crew'?'active':'')+'" data-game-style="crew"><span class="crew-symbol">\u25C9</span><strong>Crew repair</strong><small>Solve questions. Repair the study station.</small></button></div><section id="game-stage">'+gameIntro()+'</section><p class="form-help">Starter foundation practice, not an official mock or a complete syllabus. Questions may be shared across related subjects. No countdown pressure in these games.</p></div>'}
