function renderGame(){const root=$('#game-stage');if(!root||!game)return;
 if(game.index>=game.questions.length){const score=game.correct;root.innerHTML='<div class="game-finish"><span class="finish-star">\u2726</span><span class="eyebrow">QUEST COMPLETE</span><h2>'+score+' / '+game.questions.length+' concepts solved</h2><p>'+(score===game.questions.length?'Your foundations are growing. Try applying one concept in a small project.':'Mistakes show you where to practise. Revisit the explanations below, then retry.')+'</p><div class="detail-actions"><button class="btn primary" id="start-game">New quest</button><button class="btn outline" data-route="planner">Open my plan</button></div><div class="game-recap">'+game.questions.map((q,i)=>'<details><summary>'+(game.answers[i]===q.answer?'\u2713 ':'\u21BB ')+esc(q.topic)+' \u2014 '+esc(q.question)+'</summary><p>'+esc(q.explanation)+'</p></details>').join('')+'</div></div>';return}
 const q=game.questions[game.index],answered=Number.isInteger(game.answers[game.index]),chosen=game.answers[game.index];
 root.innerHTML='<article class="game-question '+gameStyle+'"><div class="game-score"><span class="tag">'+esc(q.topic)+'</span><span>Question '+(game.index+1)+' / '+game.questions.length+'</span><strong>'+game.correct*20+' XP</strong></div><div class="quest-progress" aria-label="'+game.correct+' successful answers">'+game.questions.map((_,i)=>'<span class="'+(i<game.correct?'built':'')+'">'+(gameStyle==='blocks'?'\u25A6':'\u25C9')+'</span>').join('')+'</div><h2>'+esc(q.question)+'</h2><div class="answer-options">'+q.options.map((v,i)=>'<button class="answer-option '+(answered&&(i===q.answer)?'correct':answered&&i===chosen?'incorrect':'')+'" data-game-answer="'+i+'" '+(answered?'disabled':'')+'><span>'+String.fromCharCode(65+i)+'</span>'+esc(v)+'</button>').join('')+'</div>'+(answered?'<div class="answer-explanation"><strong>'+(chosen===q.answer?'Correct \u2014 good thinking.':'The correct answer is '+String.fromCharCode(65+q.answer)+'.')+'</strong><p>'+esc(q.explanation)+'</p>'+(q.sourceUrl?'<a class="text-btn" target="_blank" rel="noopener noreferrer" href="'+safeUrl(q.sourceUrl)+'">Study the concept \u2197</a>':'')+'</div><button class="btn primary" id="next-game">'+(game.index===game.questions.length-1?'See my result':'Next question')+' \u2192</button>':'')+'</article>';
}
