 return '<div class="fade-in">'+heading('Your paper. Your practice session.','Turn an uploaded paper into an editable online test, then learn from your mistakes.')+'<div class="mock-steps"><span class="'+(!paper?'active':'')+'">01 \xB7 Import & review</span><span class="'+(mockAttempt&&!mockResult?'active':'')+'">02 \xB7 Attempt</span><span class="'+(mockResult?'active':'')+'">03 \xB7 Understand & improve</span></div><div id="mock-workspace">'+(mockResult?resultsMarkup():mockAttempt?attemptMarkup():paper?reviewMarkup():importMarkup())+'</div></div>';
