function importMarkup(){return '<div class="mock-import-grid"><section class="panel"><span class="eyebrow">BRING YOUR OWN PAPER</span><h2>Upload, or paste questions.</h2><p class="page-intro">PDF, JPG, PNG, TXT or JSON \xB7 up to 10 MB. PDF limit: 30 pages, with up to 10 scanned pages per import.</p><label class="upload-zone" for="paper-upload"><span class="square-icon">'+icon('book')+'</span><strong>Choose your mock paper</strong><small>PDF text extraction and image OCR run in your browser.</small><input type="file" id="paper-upload" accept=".pdf,.png,.jpg,.jpeg,.txt,.json"></label><div id="extract-status" class="form-help" role="status"></div><div class="two-fields"><div><label for="ocr-language">Scan language</label><select id="ocr-language"><option value="eng">English</option><option value="hin+eng">Hindi + English</option></select></div><div><label for="mock-goal">Course / exam</label><select id="mock-goal">'+goalOptions(labGoal)+'</select></div></div><label for="paper-name">Paper title</label><input id="paper-name" maxlength="120" value="My practice paper"><label for="paper-text">Extracted text / questions (editable)</label><textarea id="paper-text" rows="12" maxlength="200000" placeholder="1. Question text&#10;A. First option&#10;B. Second option&#10;C. Third option&#10;D. Fourth option&#10;Answer: B&#10;Topic: Algebra&#10;Explanation: Steps from your verified solution"></textarea><label for="answer-key">Separate answer key (optional)</label><textarea id="answer-key" rows="2" placeholder="1:B, 2:C, 3:A"></textarea><div class="detail-actions"><button class="btn primary" id="parse-paper">Build my online paper \u2192</button><button class="btn outline" id="sample-paper">Try a sample</button><button class="text-btn" id="download-template">Download import template</button></div><p id="paper-error" class="form-error" role="alert"></p></section><aside class="panel import-guide"><span class="eyebrow">A CLEARER MOCK ANALYSIS</span><h3>What you will get</h3><ol class="route-steps"><li><strong>A paper you can check</strong><p>Review extracted questions, options, topics and answer keys before starting.</p></li><li><strong>A focused online attempt</strong><p>Set the duration and marking scheme. Navigate, flag and revisit questions.</p></li><li><strong>A useful error log</strong><p>See wrong, skipped and ungraded answers. Add a mistake reason and practise the weak topics.</p></li></ol><div class="callout peach">OCR can miss formulas, diagrams or columns. Review every question against the original. This importer currently supports single-choice questions with 2\u20136 options; multi-select, numeric and descriptive questions need a different format.</div><p class="form-help">The original file stays on your device. Importing code libraries requires internet. Without a verified answer key, questions remain ungraded. Include the supplied solution if you want it shown in the review.</p></aside></div>';
}
function reviewMarkup(){return '<section class="panel"><div class="section-head"><div><span class="eyebrow">CHECK BEFORE YOU START</span><h2>'+esc(paper.title)+'</h2><p>'+paper.questions.length+' questions \xB7 '+paper.questions.filter(q=>q.answer===null).length+' without answer keys</p></div><button class="btn outline" id="new-paper">Import another</button></div><div class="review-settings"><div><label for="mock-minutes">Duration (minutes)</label><input id="mock-minutes" type="number" min="1" max="360" value="'+(paper.minutes||30)+'"></div><div><label for="mock-positive">Marks per correct</label><input id="mock-positive" type="number" min="0.1" max="100" step="0.1" value="'+(paper.marking?.correct||1)+'"></div><div><label for="mock-negative">Penalty per wrong</label><input id="mock-negative" type="number" min="0" max="100" step="0.01" value="'+(paper.marking?.wrong||0)+'"></div></div><label for="mock-syllabus">Topics to cover (one per line, optional)</label><textarea id="mock-syllabus" rows="3" placeholder="Add your syllabus topics to flag those not tested in this paper">'+esc((paper.covered||[]).join('\\n'))+'</textarea><p class="form-help">Edit any extracted question below. Keys are hidden during the test. A missing key will never be counted as a wrong answer.</p><div class="review-questions">'+paper.questions.map((q,i)=>'<details class="review-question" '+(!i?'open':'')+'><summary>Q'+(i+1)+' \xB7 '+esc(q.question.slice(0,100))+' '+(q.answer===null?'\xB7 Key needed':'')+'</summary><label>Question<textarea rows="3" data-review-field="question" data-index="'+i+'">'+esc(q.question)+'</textarea></label><div class="two-fields">'+q.options.map((o,j)=>'<label>Option '+String.fromCharCode(65+j)+'<input value="'+esc(o)+'" data-review-field="option" data-index="'+i+'" data-option="'+j+'"></label>').join('')+'</div><div class="two-fields"><label>Correct answer<select data-review-field="answer" data-index="'+i+'"><option value="" '+(q.answer===null?'selected':'')+'>Not available \u2014 leave ungraded</option>'+q.options.map((o,j)=>'<option value="'+j+'" '+(q.answer===j?'selected':'')+'>'+String.fromCharCode(65+j)+'</option>').join('')+'</select></label><label>Topic<input value="'+esc(q.topic)+'" data-review-field="topic" data-index="'+i+'"></label></div><label>Verified solution / explanation<textarea rows="3" data-review-field="explanation" data-index="'+i+'">'+esc(q.explanation)+'</textarea></label></details>').join('')+'</div><label class="check-label"><input type="checkbox" id="review-confirm"> I checked the extracted questions and answer key against my source.</label><div class="detail-actions"><button class="btn primary" id="start-mock">Start timed attempt \u2192</button><button class="btn outline" id="export-paper">Export editable paper</button></div><p id="paper-error" class="form-error" role="alert"></p></section>';
}
function persistMock(){store.set('paper',paper);store.set('mockAttempt',mockAttempt);store.set('mockResult',mockResult)}
function recordQuestionTime(){if(!mockAttempt)return;const now=Date.now();mockAttempt.timings[mockAttempt.index]=(mockAttempt.timings[mockAttempt.index]||0)+Math.max(0,(now-mockAttempt.enteredAt)/1000);mockAttempt.enteredAt=now;}
function remainingSeconds(){return mockAttempt?Math.max(0,Math.ceil((mockAttempt.deadline-Date.now())/1000)):0}
function displayTime(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function attemptMarkup(){
 const i=mockAttempt.index,q=paper.questions[i],selected=mockAttempt.answers[i];
 return '<div class="attempt-layout"><section class="panel attempt-question"><div class="game-score"><span class="tag">Question '+(i+1)+' of '+paper.questions.length+'</span><span id="mock-clock" class="mock-clock" role="timer">'+displayTime(remainingSeconds())+'</span></div><p class="form-help">'+esc(q.topic)+' \xB7 +'+paper.marking.correct+' / \u2212'+paper.marking.wrong+'</p><h2>'+esc(q.question)+'</h2><div class="answer-options">'+q.options.map((o,j)=>'<label class="answer-option '+(selected===j?'selected':'')+'"><input type="radio" name="mock-answer" value="'+j+'" '+(selected===j?'checked':'')+'><span>'+String.fromCharCode(65+j)+'</span>'+esc(o)+'</label>').join('')+'</div><div class="mock-nav"><button class="btn outline" data-mock-nav="'+(i-1)+'" '+(!i?'disabled':'')+'>\u2190 Previous</button><button class="text-btn" id="clear-answer">Clear</button><button class="btn subtle" id="flag-question">'+(mockAttempt.flags[i]?'Flagged \u2713':'Flag for review')+'</button><button class="btn primary" data-mock-nav="'+(i+1)+'" '+(i===paper.questions.length-1?'disabled':'')+'>Next \u2192</button></div></section><aside class="panel question-palette"><span class="eyebrow">'+esc(paper.title)+'</span><h3>Your questions</h3><div class="palette-buttons">'+paper.questions.map((_,n)=>'<button class="'+(n===i?'current ':'')+(Number.isInteger(mockAttempt.answers[n])?'answered ':'')+(mockAttempt.flags[n]?'flagged':'')+'" data-mock-nav="'+n+'" aria-label="Question '+(n+1)+(mockAttempt.flags[n]?', flagged':'')+'">'+(n+1)+'</button>').join('')+'</div><p class="form-help">Filled: answered \xB7 Dot: flagged<br>The timer continues while you switch pages.</p><button class="btn primary" id="finish-mock">Finish & analyse</button><div id="submit-confirm"></div></aside></div>';
}
function resumeMockClock(){if(mockTimer){clearInterval(mockTimer);mockTimer=null}if(!mockAttempt||mockResult)return;if(!remainingSeconds()){finishMock();return}mockTimer=setInterval(()=>{const secs=remainingSeconds();if($('#mock-clock'))$('#mock-clock').textContent=displayTime(secs);if(!secs)finishMock()},1000)}
function finishMock(){if(!mockAttempt||mockResult)return;recordQuestionTime();mockResult={...PaperCore.analyse(paper.questions,mockAttempt.answers,mockAttempt.timings,paper.marking,paper.covered),finishedAt:new Date().toISOString(),reasons:{}};clearInterval(mockTimer);mockTimer=null;persistMock();if(route==='mock')paintMock();toast('Your mock analysis is ready.')}
function resultsMarkup(){
 const r=mockResult;
 return '<section class="result-hero"><div><span class="eyebrow">UNDERSTAND THE ATTEMPT</span><h2>'+esc(paper.title)+'</h2><p>'+r.correct+' correct \xB7 '+r.wrong+' wrong \xB7 '+r.skipped+' skipped \xB7 '+r.ungraded+' ungraded</p></div><div class="result-number"><strong>'+Number(r.score.toFixed(2))+'<small> / '+Number(r.maxScore.toFixed(2))+'</small></strong><span>'+r.accuracy+'% accuracy on graded attempts</span></div></section>'+(r.ungraded?'<div class="callout peach">'+r.ungraded+' question(s) have no verified key. They are excluded from marks and accuracy. Add keys in Review & edit.</div>':'')+'<div class="detail-actions"><button class="btn primary" id="retry-mistakes" '+(!(r.wrong+r.skipped)?'disabled':'')+'>Practise missed questions</button><button class="btn outline" id="review-paper">Review & edit paper</button><button class="btn outline" id="export-analysis">Download analysis</button><button class="text-btn" id="new-paper">Import a new paper</button></div><h2 class="spaced-heading">Where to focus next</h2><div class="topic-analysis">'+r.topics.map(t=>'<article class="topic-card '+(t.wrong||t.skipped?'needs-work':'')+'"><div><h3>'+esc(t.topic)+'</h3><span class="tag">'+(!t.total?'Not tested':t.accuracy===null?'No graded attempt':t.accuracy+'% accuracy')+'</span></div><p>'+esc(t.action)+'</p><small>'+t.total+' questions \xB7 '+t.wrong+' wrong \xB7 '+t.skipped+' skipped \xB7 '+Math.round(t.seconds)+' seconds</small><a class="text-btn" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent(goalInfo(paper.goal||labGoal).name+' '+t.topic+' concept practice')+'">Find topic explanations \u2197</a></article>').join('')+'</div><div class="callout">Coverage gaps come only from the syllabus topics you entered. A skipped question does not prove you do not understand a topic. Use your error reasons to decide the next practice session.</div><h2 class="spaced-heading">Question-by-question error log</h2><div class="error-log">'+r.details.map((q,i)=>'<details class="error-card"><summary><span class="status-pill '+q.status+'">'+q.status+'</span> Q'+(i+1)+' \xB7 '+esc(q.question)+'</summary><p><strong>Your answer:</strong> '+(q.selected===null?'Not attempted':esc(q.options[q.selected]))+'</p><p><strong>Correct answer:</strong> '+(q.answer===null?'Key not supplied':esc(q.options[q.answer]))+'</p><div class="solution-box"><strong>'+(q.explanation?'Solution supplied with this paper':'Solution needed')+'</strong><p>'+esc(q.explanation||'This question has no supplied explanation. Check the official solution or add a verified explanation in Review & edit. The answer key alone does not establish the reasoning.')+'</p></div>'+(q.status!=='correct'?'<label for="reason-'+i+'">What caused the mistake?</label><select id="reason-'+i+'" data-error-reason="'+i+'">'+[['','Choose after reviewing'],['concept','Concept gap'],['calculation','Calculation or algebra error'],['reading','Misread the question'],['time','Ran out of time'],['guess','Guessed without enough reasoning'],['key','Question / answer key needs checking']].map(([k,l])=>'<option value="'+k+'" '+(r.reasons?.[i]===k?'selected':'')+'>'+l+'</option>').join('')+'</select><p id="reason-help-'+i+'" class="form-help">'+reasonAdvice(r.reasons?.[i])+'</p>':'')+'</details>').join('')+'</div>';
}
function reasonAdvice(key){return {concept:'Relearn the definition and one worked example, then solve 10 questions on this concept.',calculation:'Redo the steps without a timer. Check signs, units and substitutions, then attempt 5 similar calculations.',reading:'Underline what is given and what is asked. Practise 5 questions with a deliberate first reading.',time:'Solve 5 untimed questions first. Once accurate, try a short timed set and practise moving on when stuck.',guess:'Explain why each wrong option fails before retrying. Keep uncertain answers flagged for review.',key:'Compare the original official paper and key; correct the imported data before using this result.'}[key]||'Choose the cause yourself; a wrong answer alone cannot reveal why it happened.'}
async function loadOCR(language){
 if(!window.Tesseract)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('OCR library could not load. Paste the text or use a TXT/JSON file.'));document.head.append(s)});
 return window.Tesseract.createWorker(language,1,{logger:m=>{if($('#extract-status')&&m.status)$('#extract-status').textContent=m.status+' '+Math.round((m.progress||0)*100)+'%';}});
}
async function extractPaper(file){
 if(file.size>10*1024*1024)throw Error('Please use a file smaller than 10 MB.');
 const ext=file.name.split('.').pop().toLowerCase();
 if(['txt','json'].includes(ext))return file.text();
 const language=$('#ocr-language').value;let ocr=null;
 try{
  if(['jpg','jpeg','png'].includes(ext)){ocr=await loadOCR(language);return (await ocr.recognize(file)).data.text}
  if(ext!=='pdf')throw Error('Choose PDF, JPG, PNG, TXT or JSON.');
  $('#extract-status').textContent='Loading PDF reader\u2026';
  const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');
  pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';
  const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;
  if(pdf.numPages>30){await pdf.destroy();throw Error('This paper has more than 30 pages. Import a smaller page range.')}
  let text='',scanned=0;
  try{for(let n=1;n<=pdf.numPages;n++){
   $('#extract-status').textContent='Reading page '+n+' of '+pdf.numPages+'\u2026';
   const page=await pdf.getPage(n),content=await page.getTextContent();let pageText='',lastY=null;
   for(const item of content.items){const y=item.transform?.[5];if(lastY!==null&&Math.abs(y-lastY)>3)pageText+='\\n';pageText+=item.str+(item.hasEOL?'\\n':' ');lastY=y}
   if(pageText.trim().length<30){
    if(++scanned>10)throw Error('Use at most 10 scanned pages per import. Split this paper into smaller files.');
    if(!ocr)ocr=await loadOCR(language);
    const viewport=page.getViewport({scale:1.5}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;
    await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;
    pageText=(await ocr.recognize(canvas)).data.text;canvas.width=canvas.height=0;
   }
   text+=pageText+'\\n\\n';if(text.length>200000)throw Error('The extracted paper is too long. Import a smaller section.');page.cleanup();
  }}finally{await pdf.destroy()}
  return text;
 }finally{if(ocr)await ocr.terminate()}
}
function paintMock(){$$('.mock-steps span').forEach((s,i)=>s.classList.toggle('active',i===(mockResult?2:mockAttempt?1:0)));if($('#mock-workspace'))$('#mock-workspace').innerHTML=mockResult?resultsMarkup():mockAttempt?attemptMarkup():paper?reviewMarkup():importMarkup()}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;
 try{
  if(b.dataset.gameStyle){gameStyle=b.dataset.gameStyle;store.set('gameStyle',gameStyle);game=null;setRoute('practice')}
  if(b.id==='start-game'){game={questions:shuffle(bankQuestions(labGoal)).slice(0,5),index:0,correct:0,answers:[]};renderGame()}
  if(b.dataset.gameAnswer!==undefined&&game&&!Number.isInteger(game.answers[game.index])){const answer=Number(b.dataset.gameAnswer);game.answers[game.index]=answer;if(answer===game.questions[game.index].answer)game.correct++;renderGame()}
  if(b.id==='next-game'){game.index++;renderGame()}
  if(b.id==='sample-paper'){$('#paper-text').value=samplePaper;$('#paper-name').value='Sample: reasoning, data & SQL';$('#extract-status').textContent='Sample loaded. Build the paper, then review it.'}
  if(b.id==='download-template')downloadFile('mock-paper-template.txt','text/plain;charset=utf-8',samplePaper);
  if(b.id==='parse-paper'){
   const questions=PaperCore.applyKey(PaperCore.parse($('#paper-text').value),$('#answer-key').value);
   paper={title:$('#paper-name').value.trim()||'My practice paper',goal:$('#mock-goal').value,questions,minutes:30,marking:{correct:1,wrong:0},covered:[]};mockAttempt=null;mockResult=null;persistMock();paintMock();
  }
  if(b.id==='start-mock'){
   if(!$('#review-confirm').checked)throw Error('Please review the questions and confirm before starting.');
   paper.questions=PaperCore.normalise(paper.questions);
   const minutes=Number($('#mock-minutes').value),positive=Number($('#mock-positive').value),negative=Number($('#mock-negative').value);
   if(!Number.isFinite(minutes)||minutes<1||minutes>360||!Number.isFinite(positive)||positive<=0||positive>100||!Number.isFinite(negative)||negative<0||negative>100)throw Error('Check duration and marking values.');
   paper.minutes=minutes;paper.marking={correct:positive,wrong:negative};paper.covered=$('#mock-syllabus').value.split('\\n').map(s=>s.trim()).filter(Boolean).slice(0,100);
   const now=Date.now();mockAttempt={index:0,answers:{},flags:{},timings:{},startedAt:now,deadline:now+minutes*60000,enteredAt:now};mockResult=null;persistMock();paintMock();resumeMockClock();
  }
  if(b.dataset.mockNav!==undefined&&mockAttempt){const n=Number(b.dataset.mockNav);if(n>=0&&n<paper.questions.length){recordQuestionTime();mockAttempt.index=n;persistMock();paintMock()}}
  if(b.id==='clear-answer'){delete mockAttempt.answers[mockAttempt.index];persistMock();paintMock()}
  if(b.id==='flag-question'){mockAttempt.flags[mockAttempt.index]=!mockAttempt.flags[mockAttempt.index];persistMock();paintMock()}
  if(b.id==='finish-mock')$('#submit-confirm').innerHTML='<div class="submit-confirm"><p>'+Object.keys(mockAttempt.answers).length+' of '+paper.questions.length+' questions answered. Finish this attempt?</p><button class="btn primary" id="confirm-finish">Submit attempt</button><button class="text-btn" id="cancel-finish">Keep practising</button></div>';
  if(b.id==='confirm-finish')finishMock();
  if(b.id==='cancel-finish')$('#submit-confirm').innerHTML='';
  if(b.id==='review-paper'){mockAttempt=null;mockResult=null;clearInterval(mockTimer);persistMock();paintMock()}
  if(b.id==='new-paper'){const root=$('#mock-workspace');root.innerHTML='<div class="panel"><h2>Start another paper?</h2><p>Your current paper and local attempt will be replaced. Export them first if you want to keep a copy.</p><div class="detail-actions"><button class="btn primary" id="confirm-new-paper">Start new import</button><button class="btn outline" id="cancel-new-paper">Keep current paper</button></div></div>'}
  if(b.id==='cancel-new-paper')paintMock();
  if(b.id==='confirm-new-paper'){paper=null;mockAttempt=null;mockResult=null;clearInterval(mockTimer);persistMock();paintMock()}
  if(b.id==='export-paper')downloadFile('career-compass-paper.json','application/json',JSON.stringify(paper,null,2));
  if(b.id==='export-analysis')downloadFile('career-compass-mock-analysis.json','application/json',JSON.stringify({paper:paper.title,goal:paper.goal,marking:paper.marking,...mockResult},null,2));
  if(b.id==='retry-mistakes'){const missed=mockResult.details.filter(q=>['wrong','skipped'].includes(q.status));paper={...paper,title:paper.title+' \u2014 targeted retry',questions:missed.map((q,i)=>({id:String(i+1),topic:q.topic,question:q.question,options:q.options,answer:q.answer,explanation:q.explanation})),minutes:Math.max(5,missed.length*2)};mockAttempt=null;mockResult=null;persistMock();paintMock()}
 }catch(e){if($('#paper-error'))$('#paper-error').textContent=e.message;else toast(e.message)}
});
